type Tunai = { uang: number };
type Kartu = { bank: string; biaya: number };
type Cara = Tunai | Kartu;

function biayaAdmin(c: Cara): number {
  if ("uang" in c) return 0;
  return c.biaya;
}
const daftar: Cara[] = [{ uang: 50000 }, { bank: "BCA", biaya: 2500 }];
console.log(daftar.map(biayaAdmin));
try {
  JSON.parse("{rusak");
} catch (e) {
  console.log(e instanceof SyntaxError ? "JSON rusak" : "lain");
}

