type Tunai = { uang: number };
type Kartu = { bank: string; biaya: number };
function keterangan(c: Tunai | Kartu, total: number): string {
  if ("uang" in c) return "Kembalian " + (c.uang - total);
  return "Bayar " + (total + c.biaya) + " via " + c.bank;
}
console.log(keterangan({ uang: 50000 }, 42000));

