type Tunai = { uang: number };
type Kartu = { bank: string; biaya: number };
function keterangan(c: Tunai | Kartu, total: number): string {
  if ("uang" in c) return "Kembalian " + (c.uang - total);
  return "Bayar " + (total + c.biaya) + " via " + c.bank;
}
function bayarTunai(uang: number, total: number): number {
  if (uang < total) throw new Error("Uang kurang " + (total - uang));
  return uang - total;
}
console.log(keterangan({ uang: 50000 }, 42000));
console.log(keterangan({ bank: "BRI", biaya: 2000 }, 42000));
try {
  bayarTunai(30000, 42000);
} catch (e) {
  if (e instanceof Error) console.log(e.message);
}

